const API_BASE="/api";let currentData=null,currentTab="sapphire",editingId=null;async function loadData(){try{const e=await fetch("/api/updates"),t=await e.json();t.success?(currentData=t.updates,updateSectionInfo(),renderItems()):showError("Ошибка загрузки данных")}catch(e){console.error("Ошибка загрузки:",e),showError("Ошибка соединения с сервером")}}function initTabs(){document.querySelectorAll(".tab-btn").forEach(e=>{e.addEventListener("click",function(){document.querySelectorAll(".tab-btn").forEach(e=>e.classList.remove("active")),this.classList.add("active"),currentTab=this.dataset.tab,renderItems(),updateSectionInfo()})})}function updateSectionInfo(){const e=currentData?.[currentTab]?.length||0;document.querySelector(".section-info").innerHTML=`\n        <span><strong>${{sapphire:"САПФИР-3",yashma:"ЯШМА",stsh:"СТШ",external_utils:"Стороннее ПО",internal_utils:"Внутренние утилиты",docs:"Документация"}[currentTab]}</strong> — ${e} записей</span>\n        ${e>0?`<span class="item-badge">${e}</span>`:""}\n    `}function renderItems(){const e=document.getElementById("itemsContainer"),t=currentData?.[currentTab]||[];0!==t.length?e.innerHTML=t.map(e=>`\n        <div class="item-card">\n            <div class="item-header">\n                <span class="item-title">${escapeHtml(e.title)}</span>\n                <span class="item-badge">${escapeHtml(e.badge||"ZIP")}</span>\n            </div>\n            ${e.description?`<div class="item-description">${escapeHtml(e.description)}</div>`:""}\n            ${e.date?`<div class="item-date">📅 ${escapeHtml(e.date)}</div>`:""}\n            <div class="item-file">📁 ${escapeHtml(e.file)}</div>\n            <div class="item-actions">\n                <button class="edit-btn" onclick="editItem(${e.id})">✏️ Ред.</button>\n                <button class="delete-btn" onclick="deleteItem(${e.id})">🗑️ Уд.</button>\n            </div>\n        </div>\n    `).join(""):e.innerHTML='\n            <div class="empty-state">\n                <div class="icon">📂</div>\n                <h3>В этом разделе пока ничего нет</h3>\n                <p>Нажмите "Добавить" чтобы создать запись</p>\n            </div>\n        '}function initModal(){const e=document.getElementById("openAddModalBtn"),t=document.getElementById("saveItemBtn"),n=document.getElementById("cancelModalBtn"),i=document.getElementById("itemModal"),a=document.querySelector("#itemModal .close");e.addEventListener("click",()=>openAddModal()),t.addEventListener("click",()=>saveItem()),n.addEventListener("click",()=>closeModal()),a&&a.addEventListener("click",()=>closeModal()),i.addEventListener("click",e=>{e.target===i&&closeModal()})}function openAddModal(){editingId=null,document.getElementById("modalTitle").textContent="Добавить элемент",document.getElementById("itemSection").value=currentTab,document.getElementById("itemTitle").value="",document.getElementById("itemDescription").value="",document.getElementById("itemDate").value="",document.getElementById("itemFile").value="",document.getElementById("itemBadge").value="ZIP",document.getElementById("itemModal").style.display="flex"}function editItem(e){const t=currentData[currentTab].find(t=>t.id===e);t&&(editingId=e,document.getElementById("modalTitle").textContent="Редактировать элемент",document.getElementById("itemSection").value=currentTab,document.getElementById("itemTitle").value=t.title||"",document.getElementById("itemDescription").value=t.description||"",document.getElementById("itemDate").value=t.date||"",document.getElementById("itemFile").value=t.file||"",document.getElementById("itemBadge").value=t.badge||"ZIP",document.getElementById("itemModal").style.display="flex")}async function saveItem(){const e=document.getElementById("itemSection").value,t=document.getElementById("itemTitle").value.trim(),n=document.getElementById("itemDescription").value.trim(),i=document.getElementById("itemDate").value.trim(),a=document.getElementById("itemFile").value.trim(),d=document.getElementById("itemBadge").value.trim()||"ZIP";if(!t||!a)return void alert("Заполните название и путь к файлу");const c={section:e,title:t,description:n,date:i,file:a,badge:d};try{let e;e=editingId?await fetch(`/api/updates/${editingId}`,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(c)}):await fetch("/api/updates",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(c)});const t=await e.json();t.success?(await loadData(),closeModal()):alert("Ошибка: "+(t.error||"Неизвестная ошибка"))}catch(e){console.error("Ошибка:",e),alert("Ошибка соединения с сервером")}}async function deleteItem(e){if(confirm("Удалить этот элемент?"))try{const t=await fetch(`/api/updates/${e}`,{method:"DELETE"}),n=await t.json();n.success?await loadData():alert("Ошибка: "+(n.error||"Неизвестная ошибка"))}catch(e){console.error("Ошибка:",e),alert("Ошибка соединения с сервером")}}function closeModal(){document.getElementById("itemModal").style.display="none"}function showError(e){document.getElementById("itemsContainer").innerHTML=`\n        <div class="empty-state">\n            <div class="icon">⚠️</div>\n            <h3>Ошибка загрузки</h3>\n            <p>${escapeHtml(e)}</p>\n            <button class="retry-btn" onclick="location.reload()">Повторить</button>\n        </div>\n    `}function escapeHtml(e){if(!e)return"";const t=document.createElement("div");return t.textContent=e,t.innerHTML}document.addEventListener("DOMContentLoaded",function(){loadData(),initTabs(),initModal()});